import { getSP } from "../../../../services/SPService/spservice";
import { ListNames, StatusId } from "../EvaluationConfig/Config";


// ─── Response wrapper type ────────────────────────────────────────────────────
export type ApiResponse<T> = {
  data: T;
  status: number;
  message: string;
};

// ─── Domain types ─────────────────────────────────────────────────────────────
export type EvaluationCandidate = {
  SNO: number;
  ID: number;
  FristName: string;
  LastName: string;
  ApplicantName: string;
  PositionTitle: string;
  InterviewDateTime: string;
  InterviewLevel: string;
  Grade: string;
  Status: string;
  StatusId: number;
  RecruitmentID: number;
  JobCodeID: number;
  InterviewDate: string;
  InterviewDateLevel2: string;
  InterviewTime: string;
  InterviewTimeLevel2: string;
};

export type InterviewPanelRecord = {
  ID: number;
  CandidateID: number;
  CandidateIDId: number;
  RecruitmentID: number;
  InterviewLevel: string;
  InterviewPanelId: number;
  InterviewPanelEmail: string;
  InterviewPanelStringId: string;
  IsScoreSheetUploaded: string;
};

// ─── Internal SP helper ───────────────────────────────────────────────────────
async function spRead(opts: {
  listName: string;
  select?: string;
  expand?: string;
  filter?: string;
  top?: number;
}): Promise<any[]> {
  const sp = getSP();

  let q = sp.web.lists
    .getByTitle(opts.listName)
    .items.select(opts.select || "*");

  if (opts.expand) q = q.expand(opts.expand);
  if (opts.filter) q = q.filter(opts.filter);
  if (opts.top) q = q.top(opts.top);

  return await q();
}

// 1. getUserGuidByEmail
export async function getUserGuidByEmail(
  email: string
): Promise<ApiResponse<{ key: number; text: string } | null>> {
  try {
    console.log("-> getUserGuidByEmail for email:", email);
    const sp = getSP();
    const user = await sp.web.siteUsers.getByEmail(email)();
    console.log("<- getUserGuidByEmail success:", user.Id);

    return {
      data: { key: user.Id, text: user.Title },
      status: 200,
      message: "User fetched successfully",
    };
  } catch (error) {
    console.error("getUserGuidByEmail error:", error);
    return { data: null, status: 500, message: "Error fetching user" };
  }
}

// 2. getInterviewPanelByUser
export async function getInterviewPanelByUser(
  userID: number
): Promise<ApiResponse<InterviewPanelRecord[]>> {
  try {
    console.log("-> getInterviewPanelByUser for userID:", userID);
    const items = await spRead({
      listName: ListNames.HRMSInterviewPanelDetails,
      select:
        "ID,CandidateID/Id,CandidateIDId,RecruitmentID/Id,InterviewLevel," +
        "InterviewPanel/Id,InterviewPanel/EMail,InterviewPanelStringId,IsScoreSheetUploaded",
      expand: "InterviewPanel,RecruitmentID,CandidateID",
      filter: `InterviewPanel/Id eq ${userID}`,
      top: 5000,
    });
    console.log("<- getInterviewPanelByUser items count:", items.length);

    const result = items.map((item: any) => ({
      ID: item.ID,
      CandidateID: item.CandidateID?.Id ?? item.CandidateIDId ?? 0,
      CandidateIDId: item.CandidateIDId ?? 0,
      RecruitmentID: item.RecruitmentID?.Id ?? 0,
      InterviewLevel: item.InterviewLevel ?? "",
      InterviewPanelId: item.InterviewPanel?.Id ?? 0,
      InterviewPanelEmail: item.InterviewPanel?.EMail ?? "",
      InterviewPanelStringId: item.InterviewPanelStringId ?? "",
      IsScoreSheetUploaded: item.IsScoreSheetUploaded ?? "",
    }));

    return { data: result, status: 200, message: "Panel records fetched" };
  } catch (error) {
    console.error("getInterviewPanelByUser error:", error);
    return { data: [], status: 500, message: "Error fetching panel records" };
  }
}

// 3. getCandidatesByIDs
export async function getCandidatesByIDs(
  candidateIDs: number[]
): Promise<ApiResponse<any[]>> {
  try {
    console.log("-> getCandidatesByIDs for IDs:", candidateIDs);
    if (!candidateIDs.length)
      return { data: [], status: 200, message: "No IDs" };

    const idFilter = candidateIDs.map((id) => `ID eq ${id}`).join(" or ");

    const items = await spRead({
      listName: ListNames.HRMSRecruitmentCandidatePersonalDetails,
      select:
        "ID,FristName,LastName,PositionTitle,StatusId,ItemCreated," +
        "InterviewDate,InterviewTime,InterviewDateLevel2,InterviewTimeLevel2," +
        "Status/ID,Status/StatusDescription,RecruitmentID/Id,JobCode/JobCode",
      expand: "Status,RecruitmentID,JobCode",
      filter:
        `(${idFilter}) and ` +
        `(StatusId eq ${StatusId.InterviewScheduled} or StatusId eq ${StatusId.InterviewScheduledforLevel2}) and ` +
        `ItemCreated eq 'No'`,
      top: 5000,
    });
    console.log("<- getCandidatesByIDs items count:", items.length);

    return { data: items, status: 200, message: "Candidates fetched" };
  } catch (error) {
    console.error("getCandidatesByIDs error:", error);
    return { data: [], status: 500, message: "Error fetching candidates" };
  }
}

