// 5. getGradeLevel
export async function getGradeLevel(
  patersonGrade: string
): Promise<ApiResponse<{ Level: string }[]>> {
  try {
    console.log("-> getGradeLevel for grade:", patersonGrade);
    if (!patersonGrade)
      return { data: [], status: 200, message: "No grade" };

    const items = await spRead({
      listName: ListNames.HRMSGradeMaster,
      select: "*",
      filter: `PatersonGrade eq '${patersonGrade}'`,
    });
    console.log("<- getGradeLevel items count:", items.length);

    return {
      data: items.map((item: any) => ({
        Level: item.Levels ?? "",
      })),
      status: 200,
      message: "Grade level fetched",
    };
  } catch (error) {
    console.error("getGradeLevel error:", error);
    return { data: [], status: 500, message: "Error fetching grade" };
  }
}

